                if board[r][c]=='O':board[r][c]='#';q.append((r,c))
        while q:
            r,c=q.popleft()
            for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if 0<=nr<m and 0<=nc<n and board[nr][nc]=='O':board[nr][nc]='#';q.append((nr,nc))
